// Define valid country-to-cities mappings to prevent mismatched locations
const targetData = [
  {
    country: "United Kingdom",
    cities: ["London", "Manchester", "Birmingham", "Leeds", "Bristol"]
  },
  {
    country: "UAE",
    cities: ["Dubai", "Abu Dhabi", "Sharjah"]
  },
  {
    country: "Pakistan",
    cities: ["Islamabad", "Rawalpindi", "Lahore", "Karachi"]
  },
  {
    country: "Australia",
    cities: ["Sydney", "Melbourne", "Brisbane"]
  }
];

const clinicTypes = $input.first().json.clinic_types;

// Build a clean, logically valid list of combinations
const combinations = [];
for (const group of targetData) {
  for (const city of group.cities) {
    for (const clinicType of clinicTypes) {
      combinations.push({
        country: group.country,
        city: city,
        clinic_type: clinicType
      });
    }
  }
}

// Pick a random valid combination
const randomIndex = Math.floor(Math.random() * combinations.length);
const selectedTarget = combinations[randomIndex];

return [{ json: selectedTarget }];

return $input.all().map(item => {
  try {
    let groqData = {};
    if (item.json.choices && item.json.choices[0]) {
      groqData = JSON.parse(item.json.choices[0].message.content);
    }

    const originalData = item.pairedItem ? $('Web Availability1').item.json : {};

    const rawSocial = groqData.social_media_links || {};
    const fbVal = rawSocial["social_media_links[0]"] || rawSocial.facebook || groqData.facebook || "";
    const igVal = rawSocial["social_media_links[1]"] || rawSocial.instagram || groqData.instagram || "";
    const twVal = rawSocial["social_media_links[2]"] || rawSocial.twitter || groqData.twitter || "";

    delete groqData.social_media_links;

    const addressStr = originalData.data?.results?.address || item.json.address || "";
    let cityVal = groqData.city || "";
    if (!cityVal && addressStr) {
      if (addressStr.toLowerCase().includes("sharjah")) cityVal = "Sharjah";
      else if (addressStr.toLowerCase().includes("dubai")) cityVal = "Dubai";
      else if (addressStr.toLowerCase().includes("karachi")) cityVal = "Karachi";
    }

    return {
      json: {
        id: originalData.data?.results?.id || item.json.id || null,
        name: originalData.data?.results?.name || item.json.name || null,
        phone_number: originalData.data?.results?.phone_number || item.json.phone_number || null,
        address: addressStr,
        zone: originalData.data?.results?.zone || item.json.zone || null,
        country_code: originalData.data?.results?.country_code || item.json.country_code || null,
        url: originalData.data?.results?.url || item.json.url || null,
        rating: originalData.data?.results?.rating || item.json.rating || null,
        status: originalData.data?.results?.media?.status || item.json.status || null,
        opening_status: originalData.data?.results?.media?.opening_status || item.json.opening_status || null,
        website: originalData.data?.results?.media?.website || item.json.website || null,
        ...groqData,
        facebook: fbVal,
        instagram: igVal,
        twitter: twVal,
        city: cityVal,
        call_status: groqData.call_status || "Pending",
        automation_status: groqData.automation_status || "Not Started",
        notes: groqData.notes || ""
      }
    };
  } catch (error) {
    return { json: { ...item.json, error: "Failed to structure output" } };
  }
});

